'use client'

import Image from 'next/image'
import { memo, useState } from 'react'
import { isWordPressMediaUrl, DEFAULT_SIZES } from '@/lib/utils/mediaOptimization'

interface MediaImageProps {
  src: string
  alt?: string
  fallbackSrc?: string
  priority?: boolean
  sizes?: string
  className?: string
  fill?: boolean
  width?: number
  height?: number
}

const WORDPRESS_PLACEHOLDER = 'data:image/jpeg;base64,'

function MediaImageComponent({
  src,
  alt = '',
  fallbackSrc = '/placeholder-image.jpg',
  priority = false,
  sizes = DEFAULT_SIZES.card,
  className,
  fill = true,
  width,
  height,
}: MediaImageProps) {
  const [imgError, setImgError] = useState(false)
  const isWpMedia = isWordPressMediaUrl(src)
  const hasValidSrc = src && src.trim().length > 0

  const handleError = () => {
    setImgError(true)
  }

  const currentSrc = !hasValidSrc || imgError ? fallbackSrc : src
  const shouldUseNextImage = isWpMedia && hasValidSrc && !imgError

  if (shouldUseNextImage) {
    return (
      <Image
        src={currentSrc}
        alt={alt}
        priority={priority}
        sizes={sizes}
        placeholder={priority ? 'blur' : 'empty'}
        blurDataURL={priority ? WORDPRESS_PLACEHOLDER : undefined}
        className={className}
        fill={fill}
        width={fill ? undefined : width}
        height={fill ? undefined : height}
        onError={handleError}
      />
    )
  }

  return (
    <img
      src={currentSrc}
      alt={alt}
      loading={priority ? 'eager' : 'lazy'}
      decoding={priority ? 'sync' : 'async'}
      className={className}
      width={fill ? undefined : width}
      height={fill ? undefined : height}
      onError={handleError}
    />
  )
}

export const MediaImage = memo(MediaImageComponent)

export { DEFAULT_SIZES }
export type { MediaImageProps }